@import url("https://fonts.googleapis.com/css2?family=Afacad:wght@400;500;600;700&family=Akatab:wght@400;500;600;700&display=swap");

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Contenedor principal de los tres cards */
.cards-wrapper {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  gap: 30px;
  flex-wrap: wrap;
  max-width: 1400px;
  margin: 0 auto;
  padding: 80px 20px;
  background: #f5f7fa;
}

/* Cada card contenedor */
.card {
  position: relative;
  width: 386px;
  height: 345px;
  cursor: pointer;
  filter: drop-shadow(0px 4px 5.5px rgba(0, 0, 0, 0.33));
  transition: all 0.3s ease;
}

/* Ajuste de ancho específico para cada card */
.card:nth-child(1) {
  width: 376px;
}

.card:nth-child(2) {
  width: 386px;
}

.card:nth-child(3) {
  width: 385.8px;
}

/* Estado normal del card - frontal */
.card-front {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  background: #002346;
  border-radius: 10px;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 2;
}

/* Título del card normal */
.card-title {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  text-align: center;
  font-family: "Afacad";
  font-style: normal;
  font-weight: 700;
  font-size: 48px;
  line-height: 64px;
  color: #ffffff;
}

/* Ajuste específico para "¿Para qué sirve?" */
.card:nth-child(3) .card-title {
  left: 0.12%;
  right: 0.09%;
}

/* Estado hover - información desplegada (inicialmente oculta) */
.card-hover {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  background: #115aa6;
  border-radius: 10px;
  opacity: 0;
  visibility: hidden;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 3;
}

/* Al hacer hover, la información se muestra sobre el mismo card */
.card:hover .card-front {
  opacity: 0;
  visibility: hidden;
  transform: scale(0.95);
}

.card:hover .card-hover {
  opacity: 1;
  visibility: visible;
  transform: scale(1.02);
}

/* Texto descriptivo dentro del hover */
.info-text {
  position: absolute;
  width: 339px;
  left: calc(50% - 339px / 2);
  font-family: "Akatab";
  font-style: normal;
  font-weight: 700;
  font-size: 20px;
  line-height: 27px;
  text-align: center;
  color: #ffffff;
  padding: 15px;
}

/* Posiciones específicas del texto para cada card */
.card:nth-child(1) .info-text {
  top: 91px;
}

.card:nth-child(2) .info-text {
  top: 67px;
}

.card:nth-child(3) .info-text {
  top: 45px;
}

/* Icono que sobresale hacia arriba */
.icon-wrapper {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s ease;
}

/* Posiciones específicas del icono para cada card */
.card:nth-child(1) .icon-wrapper {
  left: 8.66%;
  right: 70.04%;
  top: -30px;
  width: 50px;
  height: 50px;
  background: #115aa6;
  border-radius: 10px;
}

.card:nth-child(2) .icon-wrapper {
  left: 40%;
  right: auto;
  top: -30px;
  width: 50px;
  height: 50px;
  background: #115aa6;
  border-radius: 10px;
  transform: translateX(-25%);
}

.card:nth-child(3) .icon-wrapper {
  right: 7.87%;
  top: -30px;
  width: 50px;
  height: 50px;
  background: #115aa6;
  border-radius: 10px;
}

/* El icono sobresale aún más al hacer hover */
.card:hover .icon-wrapper {
  transform: translateY(-10px);
}

.card:nth-child(2):hover .icon-wrapper {
  transform: translateX(-25%) translateY(-10px);
}

/* Icono SVG */
.icon-svg {
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.icon-svg svg {
  width: 100%;
  height: 100%;
}

/* Responsive */
@media (max-width: 900px) {
  .cards-wrapper {
    flex-direction: column;
    align-items: center;
    gap: 50px;
  }

  .card,
  .card:nth-child(1),
  .card:nth-child(2),
  .card:nth-child(3) {
    width: 100%;
    max-width: 386px;
  }
}

@media (max-width: 480px) {
  .card-title {
    font-size: 36px;
    line-height: 48px;
  }

  .info-text {
    font-size: 16px;
    line-height: 24px;
    width: 90%;
    left: 5%;
  }

  .card:nth-child(1) .info-text,
  .card:nth-child(2) .info-text,
  .card:nth-child(3) .info-text {
    top: 60px;
  }

  .icon-wrapper {
    transform: scale(0.8);
  }

  .card:nth-child(2) .icon-wrapper {
    left: 35%;
  }
}
